mapper.select:
select t.status as "status",t.TRANS_NUM as "transNum",t.REL_TRADE_AMOUNT as "relTradeAmount"
from ${param.tableName} t
where delflag_ = '1'
  
      and contractNo = #{param.contractNo}
  
  
      and TENANT_ID_ like #{param.tenantId}

mapper.update:
update ${param.tableName}
SET STATUS = #{param.status}
where DELFLAG_ = '1'

    and CONTRACT_NO like #{param.contractNo}


    and TENANT_ID_ like #{param.tenantId}
